files.game.js:
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  physics: {
    default: 'arcade',
    arcade: {
      debug: false
    }
  },
  scene: { preload, create, update }
};

let player, enemies, items, walls, cursors;
let score = 0, health = 100, scoreText, healthText;
let gameOver = false;

const game = new Phaser.Game(config);

function preload() {
  const graphics = this.make.graphics({ x: 0, y: 0, add: false });

  // Player (green circle)
  graphics.fillStyle(0x00ff00, 1);
  graphics.fillCircle(16, 16, 16);
  graphics.generateTexture('player', 32, 32);
  graphics.clear();

  // Enemy (red circle)
  graphics.fillStyle(0xff0000, 1);
  graphics.fillCircle(12, 12, 12);
  graphics.generateTexture('enemy', 24, 24);
  graphics.clear();

  // Item (yellow star)
  graphics.fillStyle(0xffff00, 1);
  graphics.fillStar(12, 12, 5, 4, 12, 0);
  graphics.generateTexture('item', 24, 24);
  graphics.clear();

  // Wall (gray)
  graphics.fillStyle(0x666666, 1);
  graphics.fillRect(0, 0, 50, 50);
  graphics.generateTexture('wall', 50, 50);
}

function create() {
  // Background
  this.add.rectangle(400, 300, 800, 600, 0x2d5016);

  // Walls
  walls = this.physics.add.staticGroup();

  // Create border walls
  for (let i = 0; i < 16; i++) {
    walls.create(i * 50 + 25, 25, 'wall').setScale(1);
    walls.create(i * 50 + 25, 575, 'wall').setScale(1);
  }
  for (let i = 1; i < 11; i++) {
    walls.create(25, i * 50 + 25, 'wall').setScale(1);
    walls.create(775, i * 50 + 25, 'wall').setScale(1);
  }

  // Add some interior walls
  walls.create(200, 200, 'wall');
  walls.create(200, 250, 'wall');
  walls.create(400, 300, 'wall');
  walls.create(600, 400, 'wall');
  walls.create(600, 200, 'wall');

  // Player
  player = this.physics.add.sprite(400, 300, 'player');
  player.setCollideWorldBounds(true);

  // Enemies
  enemies = this.physics.add.group();
  for (let i = 0; i < 5; i++) {
    const x = Phaser.Math.Between(100, 700);
    const y = Phaser.Math.Between(100, 500);
    const enemy = enemies.create(x, y, 'enemy');
    enemy.setVelocity(
      Phaser.Math.Between(-100, 100),
      Phaser.Math.Between(-100, 100)
    );
    enemy.setBounce(1);
    enemy.setCollideWorldBounds(true);
  }

  // Items
  items = this.physics.add.group();
  for (let i = 0; i < 10; i++) {
    const x = Phaser.Math.Between(100, 700);
    const y = Phaser.Math.Between(100, 500);
    items.create(x, y, 'item');
  }

  // Collisions
  this.physics.add.collider(player, walls);
  this.physics.add.collider(enemies, walls);
  this.physics.add.overlap(player, items, collectItem, null, this);
  this.physics.add.overlap(player, enemies, hitEnemy, null, this);

  // Input
  cursors = this.input.keyboard.createCursorKeys();

  // UI
  scoreText = this.add.text(16, 16, 'Items: 0/10', {
    fontSize: '20px',
    fill: '#fff'
  });
  healthText = this.add.text(16, 40, 'Health: 100', {
    fontSize: '20px',
    fill: '#fff'
  });
}

function update() {
  if (gameOver) return;

  // Player movement
  const speed = 200;
  player.setVelocity(0);

  if (cursors.left.isDown) {
    player.setVelocityX(-speed);
  } else if (cursors.right.isDown) {
    player.setVelocityX(speed);
  }

  if (cursors.up.isDown) {
    player.setVelocityY(-speed);
  } else if (cursors.down.isDown) {
    player.setVelocityY(speed);
  }

  // Normalize diagonal movement
  player.body.velocity.normalize().scale(speed);
}

function collectItem(player, item) {
  item.destroy();
  score += 1;
  scoreText.setText('Items: ' + score + '/10');

  if (score >= 10) {
    gameOver = true;
    this.add.text(400, 300, 'YOU WIN!', {
      fontSize: '64px',
      fill: '#00ff00'
    }).setOrigin(0.5);
    this.physics.pause();
  }
}

function hitEnemy(player, enemy) {
  health -= 10;
  healthText.setText('Health: ' + health);

  // Knockback
  this.physics.moveToObject(player, enemy, -200);
  this.time.delayedCall(100, () => player.setVelocity(0));

  if (health <= 0) {
    gameOver = true;
    player.setTint(0xff0000);
    this.add.text(400, 300, 'GAME OVER', {
      fontSize: '64px',
      fill: '#ff0000'
    }).setOrigin(0.5);
    this.physics.pause();
  }
}
